EXOS.push({
  ch: 'c3', id: 'c3e168', group: 'eq', num: '168', page: 107,
  title: { fr: 'Un carré égal à un nombre', it: 'Un quadrato uguale a un numero' },
  text: '<div class="calc">\n<span class="cl">a.</span><span class="cg m">(5<i>x</i> + 3)<sup>2</sup></span><span class="cd m">= 16</span>\n<span class="cl">b.</span><span class="cg m">49</span><span class="cd m">= (8<i>x</i> − 3)<sup>2</sup></span>\n</div>',
  parts: [
    { kind: 'self',
      hint: '<p class="fr"><span class="m nw"><i>X</i><sup>2</sup> = 16 <span class="ar">⇔</span> <i>X</i> = 4</span> ou <span class="m nw"><i>X</i> = −4</span>, avec <span class="m nw"><i>X</i> = 5<i>x</i> + 3</span>. On peut aussi factoriser <span class="m nw">(5<i>x</i> + 3)<sup>2</sup> − 4<sup>2</sup></span>.</p>\n<p class="it"><span class="m nw"><i>X</i><sup>2</sup> = 16 <span class="ar">⇔</span> <i>X</i> = 4</span> oppure <span class="m nw"><i>X</i> = −4</span>, con <span class="m nw"><i>X</i> = 5<i>x</i> + 3</span>. Si può anche scomporre <span class="m nw">(5<i>x</i> + 3)<sup>2</sup> − 4<sup>2</sup></span>.</p>',
      sol: '<div class="calc">\n<span class="cl">a.</span><span class="cg m">5<i>x</i> + 3</span><span class="cd m">= 4</span>\n<span class="cl"></span><span class="cg m"><span class="ui"><span class="fr">ou</span><span class="it">oppure</span></span> 5<i>x</i> + 3</span><span class="cd m">= −4</span>\n<span class="cl"></span><span class="ce m"><i>x</i> = <span class="frac"><span>1</span><span>5</span></span> <span class="ui"><span class="fr">ou</span><span class="it">oppure</span></span> <i>x</i> = −<span class="frac"><span>7</span><span>5</span></span></span>\n<span class="cl">b.</span><span class="cg m">8<i>x</i> − 3</span><span class="cd m">= 7</span>\n<span class="cl"></span><span class="cg m"><span class="ui"><span class="fr">ou</span><span class="it">oppure</span></span> 8<i>x</i> − 3</span><span class="cd m">= −7</span>\n<span class="cl"></span><span class="ce m"><i>x</i> = <span class="frac"><span>5</span><span>4</span></span> <span class="ui"><span class="fr">ou</span><span class="it">oppure</span></span> <i>x</i> = −<span class="frac"><span>1</span><span>2</span></span></span>\n</div>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3e165', group: 'eq', num: '165', page: 107,
  title: { fr: 'Se ramener à un produit nul', it: 'Ricondursi a un prodotto nullo' },
  text: '<p class="fr">On veut résoudre <span class="m nw">(<i>x</i> + 4)<sup>2</sup> = 9</span>. <br><b>1.</b> Montrer que cela revient à résoudre <span class="m nw">(<i>x</i> + 1)(<i>x</i> + 7) = 0</span>. <br><b>2.</b> Conclure.</p>\n<p class="it">Si vuole risolvere <span class="m nw">(<i>x</i> + 4)<sup>2</sup> = 9</span>. <br><b>1.</b> Mostra che equivale a risolvere <span class="m nw">(<i>x</i> + 1)(<i>x</i> + 7) = 0</span>. <br><b>2.</b> Concludi.</p>',
  parts: [
    { kind: 'self',
      sol: '<div class="calc">\n<span class="cl seul">1.</span>\n<span class="cl"></span><span class="cg m">(<i>x</i> + 4)<sup>2</sup> − 3<sup>2</sup></span><span class="cd m">= 0</span>\n<span class="cl eqv">⇔</span><span class="ce m">[(<i>x</i> + 4) − 3][(<i>x</i> + 4) + 3] = 0</span>\n<span class="cl eqv">⇔</span><span class="cg m">(<i>x</i> + 1)(<i>x</i> + 7)</span><span class="cd m">= 0</span>\n</div>\n<div class="calc">\n<span class="cl seul">2.</span>\n<span class="cl"></span><span class="cg m"><i>S</i></span><span class="cd m">= {−7\u00a0; −1}</span>\n</div>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3e62', group: 'eq', num: '62', page: 101,
  title: { fr: 'Pas à pas', it: 'Passo per passo' },
  text: '<p class="fr">On considère <span class="m nw"><span class="frac"><span><i>x</i> + 3</span><span><i>x</i> − 5</span></span> = 0</span>. <br><b>1.</b> Le membre de gauche est le quotient de deux expressions\u00a0: lesquelles\u00a0? <br><b>2.</b> 5 peut-il être solution\u00a0? <br><b>3.</b> Résoudre <span class="m nw"><i>x</i> + 3 = 0</span>. <br><b>4.</b> En déduire la solution.</p>\n<p class="it">Consideriamo <span class="m nw"><span class="frac"><span><i>x</i> + 3</span><span><i>x</i> − 5</span></span> = 0</span>. <br><b>1.</b> Il primo membro è il quoziente di due espressioni: quali? <br><b>2.</b> 5 può essere soluzione? <br><b>3.</b> Risolvi <span class="m nw"><i>x</i> + 3 = 0</span>. <br><b>4.</b> Deduci la soluzione.</p>',
  parts: [
    { kind: 'self',
      sol: '<p class="fr"><b>1.</b> <span class="m nw"><i>x</i> + 3</span> divisé par <span class="m nw"><i>x</i> − 5</span>. <br><b>2.</b> Non\u00a0: pour <span class="m nw"><i>x</i> = 5</span> le dénominateur est nul, le quotient n’existe pas. <br><b>3.</b> <span class="m nw"><i>x</i> = −3</span>. <br><b>4.</b> <span class="m nw">−3 ≠ 5</span>, donc la solution est <span class="m nw">−3</span>.</p>\n<p class="it"><b>1.</b> <span class="m nw"><i>x</i> + 3</span> diviso <span class="m nw"><i>x</i> − 5</span>. <br><b>2.</b> No: per <span class="m nw"><i>x</i> = 5</span> il denominatore è nullo, il quoziente non esiste. <br><b>3.</b> <span class="m nw"><i>x</i> = −3</span>. <br><b>4.</b> <span class="m nw">−3 ≠ 5</span>, quindi la soluzione è <span class="m nw">−3</span>.</p>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3e171', group: 'eq', num: '171', page: 107,
  title: { fr: 'Équations quotients', it: 'Equazioni con quozienti' },
  text: '<div class="calc">\n<span class="cl">a.</span><span class="cg m"><span class="frac"><span>2<i>x</i> − 6</span><span><i>x</i> − 9</span></span></span><span class="cd m">= 0</span>\n<span class="cl">b.</span><span class="cg m"><span class="frac"><span><i>x</i> + 4</span><span><i>x</i> − 1</span></span></span><span class="cd m">= 6</span>\n</div>',
  parts: [
    { kind: 'self',
      sol: '<div class="calc">\n<span class="cl">a.</span><span class="cg m"><i>x</i></span><span class="cd m">≠ 9</span>\n<span class="cl"></span><span class="cg m">2<i>x</i> − 6</span><span class="cd m">= 0</span>\n<span class="cl eqv">⇔</span><span class="cg m"><i>x</i></span><span class="cd m">= 3</span>\n<span class="cl"></span><span class="cg m">3</span><span class="cd m">≠ 9</span>\n<span class="cl"></span><span class="cg m"><i>S</i></span><span class="cd m">= {3}</span>\n<span class="cl">b.</span><span class="cg m"><i>x</i></span><span class="cd m">≠ 1</span>\n<span class="cl"></span><span class="cg m"><i>x</i> + 4</span><span class="cd m">= 6(<i>x</i> − 1)</span>\n<span class="cl eqv">⇔</span><span class="cg m"><i>x</i> + 4</span><span class="cd m">= 6<i>x</i> − 6</span>\n<span class="cl eqv">⇔</span><span class="cg m">−5<i>x</i></span><span class="cd m">= −10</span>\n<span class="cl eqv">⇔</span><span class="cg m"><i>x</i></span><span class="cd m">= 2</span>\n<span class="cl"></span><span class="cg m"><i>S</i></span><span class="cd m">= {2}</span>\n</div>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3a3', group: 'eq', num: 'A3', page: 87,
  tag: { fr: 'ACTIVITÉ', it: 'ATTIVITÀ' },
  title: { fr: 'Problème n° 17 du papyrus d’Akhmim', it: 'Problema n. 17 del papiro di Akhmim' },
  text: '<div class="fr"><p>Ce papyrus, trouvé dans la nécropole égyptienne d’Akhmim, contenait de nombreux problèmes. Énoncé du n° 17\u00a0: «\u00a0À partir d’un trésor, quelqu’un a pris le 17ᵉ\u00a0; un autre, à partir du reste, a pris le 19ᵉ et dans le trésor il est resté 200 unités. Nous voulons savoir combien il y avait dans le trésor au départ.\u00a0»</p>\n<ol>\n<li>On note <span class="m nw"><i>x</i></span> la valeur initiale du trésor. <br><b>a.</b> Exprimer la part de la première personne. <br><b>b.</b> Quelle fraction du trésor reste-t-il ensuite\u00a0? <br><b>c.</b> Expliquer pourquoi cela revient à résoudre <span class="m nw"><span class="frac"><span><i>x</i></span><span>17</span></span> + <span class="frac"><span>1</span><span>19</span></span> × <span class="frac"><span>16<i>x</i></span><span>17</span></span> + 200 = <i>x</i></span>. <br><b>d.</b> Vérifier que le trésor initial vaut <span class="m nw"><span class="frac"><span>8\u00a0075</span><span>36</span></span></span> unités.</li>\n<li>Le scribe proposait\u00a0: «\u00a017 sur 19 produit 323\u00a0; le 17ᵉ de 323 produit 19\u00a0; à partir des 323 retranche 19\u00a0: reste 304. Le 19ᵉ de 304 produit 16. À partir des 304, retranche 16\u00a0: reste 288. 323 par 200 produit 64\u00a0600, et des 64\u00a0600 le 288ᵉ, lequel est 224 1/4 1/18.\u00a0» <br><b>a.</b> Pourquoi 323\u00a0? <br><b>b.</b> Pourquoi «\u00a0retranche 19\u00a0: reste 304\u00a0»\u00a0? <br><b>c.</b> Interpréter ses calculs avec un tableau de proportionnalité. <br><b>d.</b> Trouve-t-il la même solution\u00a0?</li>\n</ol></div>\n<div class="it"><p>Questo papiro, trovato nella necropoli egizia di Akhmim, conteneva molti problemi. Testo del n. 17: «Da un tesoro qualcuno ha preso la 17ª parte; un altro, da ciò che restava, ha preso la 19ª parte e nel tesoro sono rimaste 200 unità. Vogliamo sapere quanto c’era nel tesoro all’inizio.»</p>\n<ol>\n<li>Indichiamo con <span class="m nw"><i>x</i></span> il valore iniziale del tesoro. <br><b>a.</b> Esprimi la parte presa dalla prima persona. <br><b>b.</b> Quale frazione del tesoro resta dopo? <br><b>c.</b> Spiega perché si tratta di risolvere <span class="m nw"><span class="frac"><span><i>x</i></span><span>17</span></span> + <span class="frac"><span>1</span><span>19</span></span> × <span class="frac"><span>16<i>x</i></span><span>17</span></span> + 200 = <i>x</i></span>. <br><b>d.</b> Verifica che il tesoro iniziale vale <span class="m nw"><span class="frac"><span>8\u00a0075</span><span>36</span></span></span> unità.</li>\n<li>Lo scriba proponeva: «17 per 19 fa 323; la 17ª parte di 323 fa 19; da 323 togli 19: resta 304. La 19ª parte di 304 fa 16. Da 304 togli 16: resta 288. 323 per 200 fa 64\u00a0600, e di 64\u00a0600 la 288ª parte, che è 224 1/4 1/18.» <br><b>a.</b> Perché 323? <br><b>b.</b> Perché «togli 19: resta 304»? <br><b>c.</b> Interpreta i suoi calcoli con una tabella di proporzionalità. <br><b>d.</b> Trova la stessa soluzione?</li>\n</ol></div>',
  parts: [
    { kind: 'self',
      hint: '<p class="fr">Après le premier prélèvement il reste <span class="m nw"><i>x</i> − <span class="frac"><span><i>x</i></span><span>17</span></span> = <span class="frac"><span>16<i>x</i></span><span>17</span></span></span>. Le second prend <span class="m nw"><span class="frac"><span>1</span><span>19</span></span></span> de ce reste. Pour la question 2, imagine un trésor de 323 unités.</p>\n<p class="it">Dopo il primo prelievo resta <span class="m nw"><i>x</i> − <span class="frac"><span><i>x</i></span><span>17</span></span> = <span class="frac"><span>16<i>x</i></span><span>17</span></span></span>. Il secondo prende <span class="m nw"><span class="frac"><span>1</span><span>19</span></span></span> di questo resto. Per la domanda 2, immagina un tesoro di 323 unità.</p>',
      sol: '<div class="calc">\n<p class="ct">1. a. <span class="m nw"><span class="frac"><span><i>x</i></span><span>17</span></span></span> · b. <span class="m nw"><span class="frac"><span>16</span><span>17</span></span></span> <span class="ui"><span class="fr">du trésor</span><span class="it">del tesoro</span></span></p>\n<p class="ct">c. <span class="fr">part 1 + part 2 + reste = trésor</span><span class="it inl">parte 1 + parte 2 + resto = tesoro</span>\u00a0: <span class="m nw"><span class="frac"><span><i>x</i></span><span>17</span></span> + <span class="frac"><span>1</span><span>19</span></span> × <span class="frac"><span>16<i>x</i></span><span>17</span></span> + 200 = <i>x</i></span></p>\n<span class="cl">d.</span><span class="cg m"><i>x</i> − <span class="frac"><span><i>x</i></span><span>17</span></span> − <span class="frac"><span>16<i>x</i></span><span>323</span></span></span><span class="cd m">= 200</span>\n<span class="cl eqv">⇔</span><span class="cg m"><span class="frac"><span>323<i>x</i> − 19<i>x</i> − 16<i>x</i></span><span>323</span></span></span><span class="cd m">= 200</span>\n<span class="cl eqv">⇔</span><span class="cg m">288<i>x</i></span><span class="cd m">= 64\u00a0600</span>\n<span class="cl eqv">⇔</span><span class="ce m"><i>x</i> = <span class="frac"><span>64\u00a0600</span><span>288</span></span> = <span class="frac"><span>8\u00a0075</span><span>36</span></span></span>\n<p class="ct">2. a. <span class="m nw">323 = 17 × 19</span>\u00a0: <span class="fr">un trésor «\u00a0test\u00a0» divisible par 17 puis par 19</span><span class="it inl">un tesoro «di prova» divisibile per 17 e poi per 19</span></p>\n<p class="ct">b. <span class="fr">Sur 323, le premier prend 19, il reste 304\u00a0; le second prend <span class="m nw"><span class="frac"><span>304</span><span>19</span></span> = 16</span>, il reste 288.</span><span class="it inl">Su 323 il primo prende 19, restano 304; il secondo prende <span class="m nw"><span class="frac"><span>304</span><span>19</span></span> = 16</span>, restano 288.</span></p>\n<p class="ct">c. <span class="fr">trésor 323 ⟶ reste 288\u00a0; trésor</span><span class="it inl">tesoro 323 ⟶ resto 288; tesoro</span> <span class="m nw"><i>x</i></span> ⟶ <span class="fr">reste 200, donc</span><span class="it inl">resto 200, quindi</span> <span class="m nw"><i>x</i> = <span class="frac"><span>323 × 200</span><span>288</span></span> = <span class="frac"><span>64\u00a0600</span><span>288</span></span></span></p>\n<p class="ct">d. <span class="m"><span class="mc">224 + <span class="frac"><span>1</span><span>4</span></span> + <span class="frac"><span>1</span><span>18</span></span></span> <span class="mc">= <span class="frac"><span>8\u00a0064 + 9 + 2</span><span>36</span></span></span> <span class="mc">= <span class="frac"><span>8\u00a0075</span><span>36</span></span></span></span>\u00a0: <span class="fr">même solution</span><span class="it inl">stessa soluzione</span> ✓</p>\n</div>\n<p class="fr small">Les Égyptiens n’écrivaient que des fractions de numérateur 1, d’où «\u00a0224 1/4 1/18\u00a0».</p>\n<p class="it small">Gli Egizi scrivevano solo frazioni con numeratore 1, da cui «224 1/4 1/18».</p>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3e175', group: 'eq', num: '175', page: 107,
  title: { fr: 'Bonbons', it: 'Caramelle' },
  text: '<p class="fr">Un bocal contient des bonbons à la fraise et 14 bonbons à la menthe. La proportion de bonbons à la fraise est <span class="m nw"><span class="frac"><span>9</span><span>16</span></span></span>. On note <span class="m nw"><i>n</i></span> le nombre de bonbons à la fraise. <br><b>1.</b> Montrer que <span class="m nw"><span class="frac"><span><i>n</i></span><span><i>n</i> + 14</span></span> = <span class="frac"><span>9</span><span>16</span></span></span>. <br><b>2.</b> Calculer <span class="m nw"><i>n</i></span>.</p>\n<p class="it">Un barattolo contiene caramelle alla fragola e 14 caramelle alla menta. La frazione di caramelle alla fragola è <span class="m nw"><span class="frac"><span>9</span><span>16</span></span></span>. Indichiamo con <span class="m nw"><i>n</i></span> il numero di caramelle alla fragola. <br><b>1.</b> Mostra che <span class="m nw"><span class="frac"><span><i>n</i></span><span><i>n</i> + 14</span></span> = <span class="frac"><span>9</span><span>16</span></span></span>. <br><b>2.</b> Calcola <span class="m nw"><i>n</i></span>.</p>',
  parts: [
    { kind: 'self',
      sol: '<div class="calc">\n<p class="ct">1. <span class="fr">proportion = fraise / total, et total</span><span class="it inl">frazione = fragola / totale, e totale</span> <span class="m nw">= <i>n</i> + 14</span></p>\n<span class="cl">2.</span><span class="cg m">16<i>n</i></span><span class="cd m">= 9(<i>n</i> + 14)</span>\n<span class="cl eqv">⇔</span><span class="cg m">16<i>n</i></span><span class="cd m">= 9<i>n</i> + 126</span>\n<span class="cl eqv">⇔</span><span class="cg m">7<i>n</i></span><span class="cd m">= 126</span>\n<span class="cl eqv">⇔</span><span class="cg m"><i>n</i></span><span class="cd m">= 18</span>\n<span class="cl"></span><span class="cg m"><span class="frac"><span>18</span><span>32</span></span></span><span class="cd m">= <span class="frac"><span>9</span><span>16</span></span> ✓</span>\n</div>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3e57', group: 'eq', num: '57', page: 101,
  title: { fr: 'Maths et physique : la loi d’Ohm', it: 'Matematica e fisica: la legge di Ohm' },
  text: '<p class="fr">La tension <span class="m nw"><i>U</i></span> (volts) aux bornes d’une résistance est proportionnelle à l’intensité <span class="m nw"><i>I</i></span> (ampères)\u00a0: <span class="m nw"><i>U</i> = <i>RI</i></span>, où <span class="m nw"><i>R</i></span> est la résistance (ohms). <br><b>1.</b> Exprimer <span class="m nw"><i>R</i></span> en fonction de <span class="m nw"><i>I</i></span> et <span class="m nw"><i>U</i></span>. <br><b>2.</b> Un courant de 2 milliampères traverse une résistance et la tension est de 2 volts. Quelle est la valeur de <span class="m nw"><i>R</i></span>\u00a0?</p>\n<p class="it">La tensione <span class="m nw"><i>U</i></span> (volt) ai capi di un resistore è proporzionale all’intensità <span class="m nw"><i>I</i></span> (ampere): <span class="m nw"><i>U</i> = <i>RI</i></span>, dove <span class="m nw"><i>R</i></span> è la resistenza (ohm). <br><b>1.</b> Esprimi <span class="m nw"><i>R</i></span> in funzione di <span class="m nw"><i>I</i></span> e <span class="m nw"><i>U</i></span>. <br><b>2.</b> Una corrente di 2 milliampere attraversa un resistore e la tensione è di 2 volt. Quanto vale <span class="m nw"><i>R</i></span>?</p>',
  parts: [
    { kind: 'self',
      sol: '<div class="calc">\n<span class="cl">1.</span><span class="cg m"><i>R</i></span><span class="cd m">= <span class="frac"><span><i>U</i></span><span><i>I</i></span></span></span>\n<p class="ct">2. 2 mA = 0,002 A\u00a0; <span class="m nw"><i>R</i> = <span class="frac"><span>2</span><span>0,002</span></span> = 1\u00a0000</span> ohms</p>\n</div>\n<p class="fr small">Piège\u00a0: convertir les milliampères en ampères avant de calculer.</p>\n<p class="it small">Trappola: convertire i milliampere in ampere prima di calcolare.</p>' }
  ]
});
