EXOS.push({
  ch: 'c3', id: 'c3e154', group: 'dem', num: '154', page: 107,
  title: { fr: 'Comparer à 1', it: 'Confrontare con 1' },
  text: '<p class="fr"><b>1.</b> <span class="m nw"><i>x</i> ∈ ]2\u00a0; +∞[</span> et <span class="m nw"><i>A</i>(<i>x</i>) = <span class="frac"><span><i>x</i> − 7</span><span><i>x</i> − 2</span></span></span>. <br><b>a.</b> Écrire <span class="m nw"><i>A</i>(<i>x</i>) − 1</span> comme une seule fraction. <br><b>b.</b> Comparer <span class="m nw"><i>A</i>(<i>x</i>)</span> et 1. <b>2.</b> <span class="m nw"><i>n</i></span> est un entier relatif\u00a0: comparer <span class="m nw">3<sup><i>n</i></sup></span> et <span class="m nw">3<sup><i>n</i>+1</sup></span>.</p>\n<p class="it"><b>1.</b> <span class="m nw"><i>x</i> ∈ ]2\u00a0; +∞[</span> e <span class="m nw"><i>A</i>(<i>x</i>) = <span class="frac"><span><i>x</i> − 7</span><span><i>x</i> − 2</span></span></span>. <br><b>a.</b> Scrivi <span class="m nw"><i>A</i>(<i>x</i>) − 1</span> come un’unica frazione. <br><b>b.</b> Confronta <span class="m nw"><i>A</i>(<i>x</i>)</span> e 1. <b>2.</b> <span class="m nw"><i>n</i></span> è un intero relativo: confronta <span class="m nw">3<sup><i>n</i></sup></span> e <span class="m nw">3<sup><i>n</i>+1</sup></span>.</p>',
  parts: [
    { kind: 'self',
      sol: '<div class="calc">\n<span class="cl seul">1. a.</span>\n<span class="cl"></span><span class="cg m"><i>A</i>(<i>x</i>) − 1</span><span class="cd m">= <span class="frac"><span><i>x</i> − 7 − (<i>x</i> − 2)</span><span><i>x</i> − 2</span></span></span>\n<span class="cl"></span><span class="cg m"></span><span class="cd m">= <span class="frac"><span>−5</span><span><i>x</i> − 2</span></span></span>\n</div>\n<div class="calc">\n<span class="cl seul">b.</span>\n<span class="cl"></span><span class="ce m">−5 &lt; 0 <span class="ui"><span class="fr">et</span><span class="it">e</span></span> <i>x</i> − 2 &gt; 0,</span>\n<span class="cl"></span><span class="cg m"><span class="ui"><span class="fr">donc</span><span class="it">quindi</span></span> <i>A</i>(<i>x</i>)</span><span class="cd m">< 1</span>\n</div>\n<div class="calc">\n<span class="cl seul">2.</span>\n<span class="cl"></span><span class="cg m"><span class="frac"><span>3<sup><i>n</i></sup></span><span>3<sup><i>n</i>+1</sup></span></span></span><span class="cd m">= 3<sup>−1</sup></span>\n<span class="cl"></span><span class="cg m"></span><span class="cd m">= <span class="frac"><span>1</span><span>3</span></span> &lt; 1,</span>\n<span class="cl"></span><span class="cg m"><span class="ui"><span class="fr">donc</span><span class="it">quindi</span></span> 3<sup><i>n</i></sup></span><span class="cd m">< 3<sup><i>n</i>+1</sup></span>\n</div>' }
  ]
});
EXOS.push({
  ch: 'c3', id: 'c3e158', group: 'dem', num: '158', page: 107,
  title: { fr: 'Un nombre et son inverse', it: 'Un numero e il suo reciproco' },
  text: '<p class="fr"><span class="m nw"><i>x</i></span> est strictement positif. <br><b>1.</b> Montrer que <span class="m nw"><i>x</i> + <span class="frac"><span>1</span><span><i>x</i></span></span> − 2 = <span class="frac"><span>(<i>x</i> − 1)<sup>2</sup></span><span><i>x</i></span></span></span>. <br><b>2.</b> <b>a.</b> Quel est le signe de <span class="m nw"><span class="frac"><span>(<i>x</i> − 1)<sup>2</sup></span><span><i>x</i></span></span></span>\u00a0? <br><b>b.</b> En déduire que la somme d’un nombre strictement positif et de son inverse est supérieure à 2.</p>\n<p class="it"><span class="m nw"><i>x</i></span> è strettamente positivo. <br><b>1.</b> Dimostra che <span class="m nw"><i>x</i> + <span class="frac"><span>1</span><span><i>x</i></span></span> − 2 = <span class="frac"><span>(<i>x</i> − 1)<sup>2</sup></span><span><i>x</i></span></span></span>. <br><b>2.</b> <b>a.</b> Qual è il segno di <span class="m nw"><span class="frac"><span>(<i>x</i> − 1)<sup>2</sup></span><span><i>x</i></span></span></span>? <br><b>b.</b> Deduci che la somma di un numero strettamente positivo e del suo reciproco è maggiore o uguale a 2.</p>',
  parts: [
    { kind: 'self',
      sol: '<div class="calc">\n<span class="cl">1.</span><span class="cg m"><i>x</i> + <span class="frac"><span>1</span><span><i>x</i></span></span> − 2</span><span class="cd m">= <span class="frac"><span><i>x</i><sup>2</sup> + 1 − 2<i>x</i></span><span><i>x</i></span></span></span>\n<span class="cl"></span><span class="cg m"></span><span class="cd m">= <span class="frac"><span>(<i>x</i> − 1)<sup>2</sup></span><span><i>x</i></span></span></span>\n<p class="ct">2. a. <span class="fr">un carré est positif ou nul, et</span><span class="it inl">un quadrato è positivo o nullo, e</span> <span class="m nw"><i>x</i> &gt; 0</span>\u00a0: <span class="fr">le quotient est positif ou nul</span><span class="it inl">il quoziente è positivo o nullo</span></p>\n<span class="cl">b.</span><span class="cg m"><i>x</i> + <span class="frac"><span>1</span><span><i>x</i></span></span> − 2</span><span class="cd m">≥ 0,</span>\n<span class="cn"><span class="fr">égalité seulement pour x = 1</span><span class="it inl">uguaglianza solo per x = 1</span></span>\n<span class="cl"></span><span class="cg m"><span class="ui"><span class="fr">donc</span><span class="it">quindi</span></span> <i>x</i> + <span class="frac"><span>1</span><span><i>x</i></span></span></span><span class="cd m">≥ 2</span>\n</div>' }
  ]
});
