  text: '<div class="calc">\n<span class="cl">1.</span><span class="cg m"><span class="sqrt"><span class="rad">18</span></span> + <span class="sqrt"><span class="rad">32</span></span> − <span class="sqrt"><span class="rad">50</span></span></span><span class="cd m">= 0</span>\n<span class="cl">2.</span><span class="cg m"><span class="sqrt"><span class="rad">27</span></span> + <span class="sqrt"><span class="rad">12</span></span> − <span class="sqrt"><span class="rad">48</span></span></span><span class="cd m">= <span class="sqrt"><span class="rad">3</span></span></span>\n<span class="cl">3.</span><span class="cg m">(1 + <span class="sqrt"><span class="rad">3</span></span>)<sup>2</sup></span><span class="cd m">= 4</span>\n</div>',
